def zig(steps,P,N):
    if sorted(x for x in steps if x>0)!=sorted(P) or sorted(-x for x in steps if x<0)!=sorted(N): return False
    v=0;seen=set()
    for d in steps:
        if (v<=0)!=(d>0) or v in seen: return False
        seen.add(v);v+=d
    return v==0
ok=sum(zig(w['steps'],range(1,w['M']+1),sorted(set(range(1,w['M']+2))-{w['a'],w['M']+1-w['a']})) for w in W)
print("M=15/16 certificates valid:",ok,"/",len(W))
# 13.1 large-opposite: random test
bad=0;tests=0
for _ in range(20000):
    P=random.sample(range(1,40),random.randint(1,5));N=random.sample(range(1,40),random.randint(1,5))
    if sum(P)!=sum(N) or sorted(P)==sorted(N): continue
    p,q=max(P),max(N)
    if p+q<=sum(P): continue
    tests+=1
    st=[p]+[-n for n in N if n!=q]+[-q]+[x for x in P if x!=p]
    bad+=not zig(st,P,N)
print("13.1 random tests",tests,"failures",bad)
